-function benutzer_array(int $limit = 100): array
+function benutzer_array(int $limit = 100, ?string $suche = null, ?string $status = null): array
 {
     $db = datenbank_verbindung();
     if (!$db) {
         return [];
     }

-    $abfrage = $db->prepare('SELECT * FROM benutzer ORDER BY aktiv DESC, gesperrt ASC, id DESC LIMIT :limit');
+    // Status-Filterung vorbereiten
+    $where = '';
+    $params = [];
+
+    if ($status !== null && in_array($status, ['alle', 'aktiv', 'inaktiv', 'gesperrt'], true)) {
+        switch ($status) {
+            case 'aktiv':
+                $where .= ' AND aktiv = 1 AND gesperrt = 0';
+                break;
+            case 'inaktiv':
+                $where .= ' AND aktiv = 0';
+                break;
+            case 'gesperrt':
+                $where .= ' AND gesperrt = 1';
+                break;
+        }
+    }
+
+    // Suchfilterung vorbereiten
+    if ($suche !== null && trim($suche) !== '') {
+        $suche = trim($suche);
+        if (strlen($suche) > 120) {
+            $suche = substr($suche, 0, 120);
+        }
+
+        // Suchfelder: benutzername, anzeigename, email, vorname, nachname
+        $where .= ' AND (
+            benutzername LIKE :suche OR
+            anzeigename LIKE :suche OR
+            email LIKE :suche OR
+            vorname LIKE :suche OR
+            nachname LIKE :suche
+        )';
+        $params[':suche'] = '%' . $suche . '%';
+    }
+
+    $sql = 'SELECT * FROM benutzer WHERE 1=1' . $where . ' ORDER BY aktiv DESC, gesperrt ASC, id DESC LIMIT :limit';
+
+    $abfrage = $db->prepare($sql);
     $abfrage->bindValue(':limit', max(1, min($limit, 500)), PDO::PARAM_INT);
+
+    foreach ($params as $key => $value) {
+        $abfrage->bindValue($key, $value);
+    }
+
     $abfrage->execute();
     return $abfrage->fetchAll() ?: [];
 }
